        "Формы: er bringt, brachte, hat gebracht. Обычно есть два дополнения: кому? (дательный падеж) и что? (винительный падеж): Er bringt mir das Buch.",
        "Русские 'принести' и 'отнести' в немецком передаются одним словом bringen; направление показывает контекст или предлог (zu, nach)."
