        "У мужского и среднего рода — ein, у женского — eine. В винительном падеже у мужского рода — einen: Ich habe einen Bruder. В дательном: einem (мужской/средний род), einer (женский род). Неопределённого артикля во множественном числе нет; при отрицании используется kein.",
