      "layout": "standardStudy",
      "translation": "ехать • ездить",
      "explanation": [
        "fahren значит ехать, то есть передвигаться на транспорте: Wir fahren mit dem Bus, Er fährt nach Berlin. Оно может значить и «водить» транспортное средство: Sie fährt einen Mercedes.",
        "Формы: du fährst, er fährt (a → ä), fuhr, ist gefahren. Если прямого дополнения нет, используется sein: Ich bin nach Wien gefahren. Если есть винительный падеж (вождение автомобиля), используется haben: Ich habe das Auto gefahren.",
        "На вопрос куда? говорят nach (город, страна), zu (человек, место) или in + винительный падеж; для транспортных средств используется mit + дательный падеж."
      ],
