        "Формы: es gefällt, gefiel, hat gefallen. Если нравится несколько предметов, глагол стоит во множественном числе: Die Schuhe gefallen mir.",
        "Gefallen выражает непосредственное впечатление (внешний вид, опыт); для длительной симпатии (еда, человек) чаще используется mögen."
