        "Используется только с существительными среднего рода (das Kino, das Haus, das Bett). Для мужского рода — in den (in den Garten), для женского — in die (in die Schule).",
        "Часто встречается в выражениях: ins Bett gehen (идти спать), ins Ausland fahren (ехать за границу), ins Wasser springen (прыгать в воду)."
