      "layout": "standardStudy",
      "translation": "бежать • бегать • работать (о механизме)",
      "explanation": [
        "Главное: laufen означает «бежать» или «идти пешком»: Er läuft sehr schnell. В переносном значении это также «работать» и «происходить»: Die Maschine läuft gut, Der Film läuft schon (фильм уже идёт).",
        "Формы: ich laufe, du läufst, er läuft; lief, ist gelaufen. Вспомогательный глагол — sein: Er ist gelaufen. Спрашивают: Wie läuft’s? — Как дела?",
        "С указанием направления laufen означает «идти пешком», а не «ехать»: Wir laufen zur Schule. Быстрый бег часто выражается словом rennen."
      ],
