        "Выражения: keinen Laut von sich geben (не издавать ни звука), ein Laut der Überraschung (возглас удивления). В языкознании: Vokale und Konsonanten sind Laute.",
        "Отличие от laut: laut — прилагательное “громкий”; Laut — существительное “звук”. Музыкальный тон и шум называются Ton и Geräusch."
