        "Частые сочетания: morgen früh (завтра утром), morgen Abend (завтра вечером), bis morgen (до завтра), übermorgen (послезавтра). Части суток после morgen пишутся с большой буквы: morgen Nachmittag.",
        "Отличие от Morgen: der Morgen — существительное «утро», а morgen — наречие «завтра». В начале предложения их различают только по смыслу."
