      "explanation": [
        "Слово neu значит «новый» о вещах и явлениях, которые появились или куплены недавно: ein neues Handy, eine neue Wohnung, neue Schuhe. О возрасте человека говорят jung.",
        "Перед существительным neu склоняется: ein neuer Tisch, eine neue Jacke, ein neues Auto, neue Freunde. Сравнительная степень: neuer, превосходная: am neuesten. После sein — без окончания: Mein Handy ist neu.",
        "О человеке neu значит «недавно появившийся, новый на работе или в классе»: ein neuer Kollege, eine neue Lehrerin."
      ],
      "examples": [
        {
          "de": "Mein Handy ist neu.",
          "lv": "Мой телефон новый."
        },
        {
          "de": "Wir haben ein neues Auto.",
          "lv": "У нас новая машина."
        },
        {
          "de": "Das ist meine neue Wohnung.",
          "lv": "Это моя новая квартира."
        },
        {
          "de": "Ich habe neue Schuhe gekauft.",
          "lv": "Я купил новые туфли."
        },
        {
          "de": "Wir haben einen neuen Kollegen.",
          "lv": "У нас новый коллега."
        }
      ],
      "comparison": [
        {
          "word": "jung",
          "meaning": "молодой (о человеке)",
          "example": "Meine Tante ist jung. – Моя тётя молодая."
        },
        {
          "word": "alt",
          "meaning": "старый",
          "example": "Das Haus ist alt. – Дом старый."
        },
        {
          "word": "modern",
          "meaning": "современный",
          "example": "Das Büro ist modern. – Офис современный."
        }
      ],
      "tip": [
        "Противоположности: neu ≠ alt (новый ≠ старый); jung ≠ alt (молодой ≠ старый, о человеке).",
        "Neu можно сочетать с другими словами: neu eröffnet (недавно открывшийся), neu bauen (построить заново)."
      ],
      "important": [
        "О возрасте человека обычно говорят jung, а не neu.",
        "Neu (новый) и neun (девять) — разные слова."
      ],
