      "layout": "standardStudy",
      "translation": "видеть • увидеть",
      "explanation": [
        "Слово sehen значит видеть глазами — воспринимать то, что находится вокруг или впереди. Это сильный глагол: ich sehe, du siehst, er sieht (e меняется на ie), прошедшее время sah, Perfekt hat gesehen.",
        "Обычно присоединяет дополнение в винительном падеже: Ich sehe einen Hund. Возвратная форма sich sehen значит встречаться или видеть друг друга: Wir sehen uns morgen.",
        "Если смотрят сознательно, дольше или на что-то определённое, обычно используют schauen или ansehen; sehen чаще выражает сам факт зрительного восприятия."
      ],
      "examples": [
        {
          "de": "Ich sehe einen Vogel im Garten.",
          "lv": "Я вижу птицу в саду."
        },
        {
          "de": "Siehst du das Haus dort?",
          "lv": "Ты видишь тот дом?"
        },
        {
          "de": "Ohne Brille sieht er schlecht.",
          "lv": "Без очков он плохо видит."
        },
        {
          "de": "Wir sehen uns morgen.",
          "lv": "Увидимся завтра."
        },
        {
          "de": "Hast du gestern den Film gesehen?",
          "lv": "Ты вчера видел этот фильм?"
        }
      ],
      "comparison": [
        {
          "word": "schauen",
          "meaning": "смотреть",
          "example": "Schau mal, der Hund! – Смотри, собака!"
        },
        {
          "word": "ansehen",
          "meaning": "рассматривать",
          "example": "Ich sehe mir das Bild an. – Я рассматриваю картину."
        },
        {
          "word": "blicken",
          "meaning": "глядеть",
          "example": "Sie blickt aus dem Fenster. – Она глядит в окно."
        }
      ],
      "tip": [
        "Запомни формы du siehst / er sieht — это одна из самых частых ошибок, потому что e меняется на ie.",
        "Sehen значит также «понимать» в выражениях вроде Ich sehe, was du meinst."
      ],
      "important": [
        "Форм sehst или sehet нет: правильно du siehst, er sieht.",
        "Чтобы сказать, что кто-то что-то смотрит (фильм, картину), можно использовать и sehen, и sich (Dat) + ansehen."
      ],
