        "Для других лиц используются другие формы: ich – mich, du – dich, wir – uns, ihr – euch. Например, er wäscht sich (он умывается), но ich wasche mich.",
        "Многие немецкие глаголы возвратные (sich freuen, sich setzen, sich vorstellen), и им часто соответствуют глаголы на -ся: радоваться, садиться."
